			function saveControl(psType) {
			    
			    var vcHtmlEdit = app.lookup("cmnHtmlEditor");
			    var vsContent = vcHtmlEdit.getValue();
			    var vcfld = app.lookup("cmnMultifileupload");
			    
			    
			    // 에디터 저장.
			    util.DataSet.setValue(app, "dsList", 0, "DOC_INO_CN", vsContent);
			    util.DataSet.setValue(app, "dsList", 0, "IOBX_SE_CD", "S");
			    var ttlNm = util.DataSet.getValue(app, "dsList", 0, "INO_DOC_TTL_NM");
			    if ("" == ttlNm || null == ttlNm) {
			        util.Msg.alert(app, "제목을 입력해 주세요.");
			        return;
			    }
			    if ("" == vsContent || null == vsContent) {
			        util.Msg.alert(app, "내용을 입력해주세요.");
			        return;
			    }
			    if(2000 < vsContent.length){
			        util.Msg.alert(app, "내용이 너무 깁니다. \n한글기준 2,000자 까지만 입력이 가능합니다.");
			        return;
			    }
			    //유효성 체크
			    if (!util.validate(app, "grpDetail")) return;
			    
			    // 내게 쓴 문서함 기준이라. UPDATE와 SVAE 의 차이가 없을 듯.
			    if (util.DataSet.getValue(app, "dsList", 0, "INO_DOC_ESNTAL_NO") == "") {
			        util.Msg.confirm(app, "CRM-M001", null, function() {
			            util.DataSet.setValue(app, "dsList", 0, "TYPE", "SAVE");
			            vcfld.send(doSave);
			        });
			    } else {
			        util.Msg.confirm(app, "CRM-M001", null, function() {
			            util.DataSet.setValue(app, "dsList", 0, "TYPE", "UPDATE");
			            vcfld.send(doSave);
			        });
			    }
			    
			}

